local utils = require 'mp.utils'local LUT_EXTS = { cube = true, ["3dl"] = true, lut = true, mga = true }local luts = {}local current_index = 0local function scan_luts()    luts = {}    local dir = mp.command_native({"expand-path", "~~/luts"})    local files = utils.readdir(dir, "files")    if not files then return end    for _, file in ipairs(files) do        local ext = file:match("%.([^%.]+)$")        if ext and LUT_EXTS[ext:lower()] then            luts[#luts + 1] = {                path = utils.join_path(dir, file),                name = file:gsub("%.[^%.]+$", ""),            }        end    end    table.sort(luts, function(a, b) return a.name < b.name end)endlocal function apply_lut(index)    if index == 0 then        mp.set_property("lut", "")        mp.osd_message("LUT None", 2)        return    end    local lut = luts[index]    mp.set_property("lut", lut.path)    mp.osd_message(string.format("LUT %d/%d %s", index, #luts, lut.name), 2)endlocal function cycle_lut(direction)    if #luts == 0 then scan_luts() end    if #luts == 0 then        mp.osd_message("No LUTs found in ~~/luts", 3)        return    end    current_index = current_index + direction    if current_index > #luts then        current_index = 0    elseif current_index < 0 then        current_index = #luts    end    apply_lut(current_index)endscan_luts()mp.add_key_binding("e", "lut-cycle-next", function() cycle_lut(1) end)mp.add_key_binding("E", "lut-cycle-prev", function() cycle_lut(-1) end)